import re
from typing import List, Dict, Any, Tuple, Optional

# Helpers assumed to exist
# node_by_title(doc, title) -> node
# node_by_id(doc, node_id) -> node
# children(doc, node) -> list of node
# table_rows(node) -> [(row_index, {column: cell})]

def entities(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    """Return the list of entities (objects) described in the scope."""
    scope_node = node_by_title(doc, scope)
    # Find the Objects list
    obj_node = next((c for c in children(doc, scope_node)
                     if c["title"].startswith("Objects")), None)
    if obj_node is None:
        return []
    ents = []
    for line in obj_node["lines"]:
        # Expected form: "Object 0: blue metal sphere (color=blue, material=metal, shape=... )"
        m = re.match(r"\s*Object\s+(\d+)\s*:\s*(.+)", line)
        if m:
            obj_id = m.group(1)
            desc = m.group(2).strip()
            ents.append({"id": obj_id, "description": desc})
    return ents


def recorded_end(doc: Dict, scope: str) -> Optional[float]:
    """Return the last frame number recorded for this scope."""
    scope_node = node_by_title(doc, scope)
    motion_node = next((c for c in children(doc, scope_node)
                        if c["title"].startswith("Motion log")), None)
    if motion_node is None:
        return None
    max_frame = None
    for _index, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
            max_frame = f if max_frame is None or f > max_frame else max_frame
        except ValueError:
            continue
    return float(max_frame) if max_frame is not None else None


def _parse_events(doc: Dict, scope: str) -> Tuple[List[Dict], List[Dict]]:
    """Parse the Events list and return lists of input & outcome descriptions."""
    scope_node = node_by_title(doc, scope)
    events_node = next((c for c in children(doc, scope_node)
                        if c["title"].startswith("Events")), None)
    if events_node is None:
        return [], []

    inputs = []
    outcomes = []
    inp_id = 0
    out_id = 0
    for i, line in enumerate(events_node["lines"]):
        # Common pattern: "Frame X: Object N (desc) ..."
        m = re.match(r"\s*Frame\s+(\d+)\s*:\s*Object\s+(\d+)\s*(?:\(([^)]*)\))?\s*(.*)", line)
        if not m:
            continue
        frame = int(m.group(1))
        obj_id = m.group(2)
        desc = m.group(3)  # optional inside parentheses
        rest = m.group(4).strip()

        # Check for in view / enter / exit / collision
        if "is in view when the video begins" in rest:
            # input appearance at start
            inputs.append({
                "id": f"in_{inp_id}",
                "time": float(frame),
                "kind": "in_view",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], i]]
            })
            inp_id += 1
        elif re.search(r"enters the scene", rest):
            inputs.append({
                "id": f"in_{inp_id}",
                "time": float(frame),
                "kind": "enter",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], i]]
            })
            inp_id += 1
        elif re.search(r"exits the scene", rest):
            outcomes.append({
                "time": float(frame),
                "kind": "exit",
                "entities": [obj_id],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })
            out_id += 1
        elif match := re.search(r"collides with Object\s+(\d+)", rest):
            other_id = match.group(1)
            outcomes.append({
                "time": float(frame),
                "kind": "collision",
                "entities": [obj_id, other_id],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })
            out_id += 1
        else:
            # Unknown event type => treat as outcome placeholder
            outcomes.append({
                "time": float(frame),
                "kind": "event",
                "entities": [obj_id],
                "value": None,
                "src": [[events_node["node_id"], i]]
            })
            out_id += 1
    return inputs, outcomes


def _initial_state_inputs(doc: Dict, scope: str, entity_ids: set) -> List[Dict]:
    """Return inputs derived from the first motion log records for start‑state objects."""
    inp = []
    inp_id = 0
    scope_node = node_by_title(doc, scope)
    motion_node = next((c for c in children(doc, scope_node)
                        if c["title"].startswith("Motion log")), None)
    if motion_node is None:
        return inp

    # Build a dict of the first rows for each object at frame 0
    first_rows: Dict[str, Tuple[int, Dict[str, str]]] = {}
    for row_index, row in table_rows(motion_node):
        try:
            f = int(row["frame"])
        except ValueError:
            continue
        obj_field = row["object"]  # e.g. "1 purple rubber cube"
        # Extract id: digits at start
        m = re.match(r"(\d+)\s+", obj_field)
        if not m:
            continue
        obj_id = m.group(1)
        if obj_id not in entity_ids:
            continue
        if f == 0:
            if obj_id not in first_rows:
                first_rows[obj_id] = (row_index, row)

    for obj_id, (row_index, row) in first_rows.items():
        fields = {"x": float(row["x"]),
                  "y": float(row["y"]),
                  "vx": float(row["vx"]),
                  "vy": float(row["vy"]),
                  "speed": float(row["speed"])}
        inp.append({
            "id": f"init_{inp_id}",
            "time": 0.0,
            "kind": "initial_state",
            "entities": [obj_id],
            "fields": fields,
            "src": [[motion_node["node_id"], row_index,
                     ["x", "y", "vx", "vy", "speed"]]]
        })
        inp_id += 1
    return inp


def inputs(doc: Dict, scope: str) -> List[Dict]:
    """Return all inputs to the process in the given scope."""
    ents = entities(doc, scope)
    entity_ids = {e["id"] for e in ents}

    ev_inputs, ev_outcomes = _parse_events(doc, scope)
    init_inputs = _initial_state_inputs(doc, scope, entity_ids)

    # Combine inputs
    return ev_inputs + init_inputs


def outcomes(doc: Dict, scope: str) -> List[Dict]:
    """Return all outcomes produced by the process in the given scope."""
    ev_inputs, ev_outcomes = _parse_events(doc, scope)
    return ev_outcomes


def params(doc: Dict, scope: str) -> Dict[str, Any]:
    """Constants expressed in the scope.  No constants here."""
