# Compute average speed of each object over the whole video
def avg_speed(scope):
    motion_node = None
    for n in children(doc, node_by_title(doc, scope)):
        if n["title"].endswith(": Motion log"):
            motion_node = n
            break
    if not motion_node:
        return {}
    speeds = {}
    for _, row in table_rows(motion_node):
        obj_id = re.match(r"(\d+)\s+", row["object"]).group(1)
        speeds.setdefault(obj_id, []).append(float(row["speed"]))
    return {obj: sum(vs)/len(vs) for obj, vs in speeds.items()}

