def collision_separation(scope):
    motion_node, events_node = None, None
    for n in children(doc, node_by_title(doc, scope)):
        if n["title"].endswith(": Motion log"):
            motion_node = n
        if n["title"].endswith(": Events"):
            events_node = n
    if not motion_node or not events_node:
        return
    # build dict of frames -> object pos
    pos = {}
    for _, row in table_rows(motion_node):
        f = int(row["frame"])
        obj_id = re.match(r"(\d+)\s+", row["object"]).group(1)
        pos.setdefault(f, {})[obj_id] = (float(row["x"]), float(row["y"]))
    for line in events_node.get("lines", []):
        m = re.match(r"Frame\s+(\d+)\s*:\s*Object\s+(\d+).*collides with Object\s+(\d+)", line)
        if not m: continue
        f = int(m.group(1))
        a, b = m.group(2), m.group(3)
        if f in pos and a in pos[f] and b in pos[f]:
            ax, ay = pos[f][a]
            bx, by = pos[f][b]
            d = math.hypot(ax-bx, ay-by)
            print(f"{scope} collision at {f}s between {a} & {b}: distance {d:.3f}")
            # expected < 1.0 if radii ~0.5 each
    print()

