# 3) Compare speeds just before and after each collision in Video 14996
def collision_speed_change(scope):
    # find collisions
    ev_node = None
    for n in children(doc, node_by_title(doc, scope)):
        if n["title"].endswith(": Events"):
            ev_node = n
            break
    motions = {}
    for n in children(doc, node_by_title(doc, scope)):
        if n["title"].endswith(": Motion log"):
            for idx, row in table_rows(n):
                f = int(row["frame"])
                obj = re.match(r"(\d+)\s+", row["object"]).group(1)
                speed = float(row["speed"])
                motions.setdefault(obj, []).append((f, speed))

    # Helper to get speed at or before a frame
    def get_speed(obj, frame):
        lst = motions[obj]
        # find last frame <= target
        last = None
        for f, s in lst:
            if f > frame:
                break
            last = s
        return last

    for line in ev_node["lines"] if ev_node else []:
        m = re.match(r"Frame\s+(\d+)\s*:.*collides with Object\s+(\d+)", line)
        if not m: continue
        f = int(m.group(1))
        obj1 = m.group(2)
        # find second object from line
        m2 = re.search(r"collides with Object\s+(\d+)", line)
        obj2 = m2.group(1) if m2 else None
        if obj2:
            s1_before = get_speed(obj1, f-1)
            s1_after = get_speed(obj1, f+1)
            s2_before = get_speed(obj2, f-1)
            s2_after = get_speed(obj2, f+1)
            print(f"Collision at {f}s between {obj1} and {obj2}:")
            print(f"  {obj1} speed: before={s1_before}, after={s1_after}")
            print(f"  {obj2} speed: before={s2_before}, after={s2_after}")
            print()

