def simulate(doc: Dict[str, Any], scope: str,
             inputs: List[Dict[str, Any]], params: Dict[str, Any],
             start: float = None, horizon: float = None) -> List[Dict[str, Any]]:
    # Default horizon to recorded end if not provided
    rec_end = recorded_end(doc, scope)
    start = 0.0 if start is None else float(start)
    horizon = float(horizon) if horizon is not None else rec_end

    # --------------------------------------------------------------
    # 1. Gather motion log state records
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    motion_node_id = motion_node["node_id"] if motion_node else None
    rows = table_rows(motion_node) if motion_node else []

    # Build per-frame snapshot of states and keep row indices
    frames: Dict[int, Dict[str, Tuple[Dict[str, float], int]]] = {}
    for row_idx, row in rows:
        try:
            f = int(row["frame"])
        except Exception:
            continue
        if f > horizon:
            continue
        obj_str = row["object"]
        m = re.match(r"(\d+)\s+", obj_str)
        if not m:
            continue
        obj_id = m.group(1)
        state = {
            "x": float(row["x"]),
            "y": float(row["y"]),
            "vx": float(row["vx"]),
            "vy": float(row["vy"]),
            "speed": float(row["speed"]),
        }
        frames.setdefault(f, {})[obj_id] = (state, row_idx)

    # Generate state_record outcomes for frames >= start
    state_outcomes: List[Dict[str, Any]] = []
    for f, snap in sorted(frames.items()):
        if f < start:
            continue
        for obj_id, (_, row_idx) in snap.items():
            state_outcomes.append({
                "time": float(f),
                "kind": "state_record",
                "entities": [obj_id],
                "value": None,
                "src": [[motion_node_id, row_idx]]
            })

