        for idx, line in enumerate(events_node.get("lines", [])):
            m = re.match(r"Frame\s+(\d+)\s*:\s*Object\s+(\d+)(?:\s*\(([^)]*)\))?\s*(.*)", line)
            if not m:
                continue
            frame = int(m.group(1))
            obj_id = m.group(2)
            rest = m.group(4).strip()
            if "collides with Object" in rest:
                m2 = re.search(r"collides with Object\s+(\d+)", rest)
                other_id = m2.group(1) if m2 else None
                if other_id and frame >= start and frame <= horizon:
