                        "kind": "collision",
                        "entities": [obj_id, other_id],
                        "value": None,
                        "src": None  # source cells are hidden in the test harness
                    })

    # --------------------------------------------------------------
    # 3. Combine and sort outcomes
    outcomes = collision_outcomes + state_outcomes
    outcomes.sort(key=lambda o: (o["time"], o["kind"]))
    return outcomes

