            "fields": fields,
            "src": [[motion_node["node_id"], idx, ["x", "y", "vx", "vy", "speed"]]]
        })
    return inputs


def _parse_events_list(doc: Dict[str, Any], scope: str) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
    """
    Parse the Events list and separate input‑style events (enter/exit) from
    outcome‑style collisions or other transitions.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return [], []

    events_node = None
    for c in children(doc, scope_node):
        if c["title"].endswith(": Events"):
            events_node = c
            break
    if not events_node:
        return [], []

    inputs: List[Dict[str, Any]] = []
    outcomes: List[Dict[str, Any]] = []

    for idx, line in enumerate(events_node.get("lines", [])):
        # Frame X: Object N (desc) <action>
        m = re.match(r"Frame\s+(\d+)\s*:\s*Object\s+(\d+)(?:\s*\(([^)]*)\))?\s*(.*)", line)
        if not m:
            continue
        frame = int(m.group(1))
        obj_id = m.group(2)
        rest = m.group(4).strip()

        if "enters the scene" in rest or "is in view when the video begins" in rest:
            inputs.append({
                "id": f"ev_in_{len(inputs)}",
                "time": float(frame),
                "kind": "entity_arrival",
                "entities": [obj_id],
                "fields": {},
                "src": [[events_node["node_id"], idx]]
            })
        elif "exits the scene" in rest:
            outcomes.append({
                "time": float(frame),
                "kind": "entity_exit",
                "entities": [obj_id],
                "value": None,
                "src": [[events_node["node_id"], idx]]
            })
        elif "collides with Object" in rest:
            # extract collided object
            m_ = re.search(r"collides with Object\s+(\d+)", rest)
            other_id = m_.group(1) if m_ else None
            if other_id:
                outcomes.append({
                    "time": float(frame),
                    "kind": "collision",
                    "entities": [obj_id, other_id],
                    "value": None,
                    "src": [[events_node["node_id"], idx]]
                })
        else:
            # fallback: treat as generic outcome
            outcomes.append({
                "time": float(frame),
                "kind": "event",
                "entities": [obj_id],
                "value": None,
                "src": [[events_node["node_id"], idx]]
            })
    return inputs, outcomes


def _parse_motion_log_outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Treat each row in the motion log as an outcome that records the state
    of an object at a specific frame.
    """
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    motion_node = None
    for c in children(doc, scope_node):
        if c["title"].endswith(": Motion log"):
            motion_node = c
            break
    if not motion_node:
        return []

    outcomes: List[Dict[str, Any]] = []
    for idx, row in table_rows(motion_node):
        try:
            frame = float(row["frame"])
        except Exception:
            continue
        # Extract object id from the "object" cell
        m = re.match(r"(\d+)\s+", row["object"])
        if not m:
            continue
        obj_id = m.group(1)
        outcomes.append({
            "time": frame,
            "kind": "state_record",
            "entities": [obj_id],
            "value": None,
            "src": [[motion_node["node_id"], idx]]
        })
    return outcomes


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return all inputs to the process in the given scope.
    """
    # Collect entity definitions first
    entity_inputs = _parse_object_definitions(doc, scope)

    # Entity IDs for later filtering
    entity_ids = {e["id"] for e in entities(doc, scope)}

    # Initial state inputs from motion log frame 0
    state_inputs = _parse_initial_states(doc, scope, entity_ids)

    # Event inputs from Events list
    event_inputs, _ = _parse_events_list(doc, scope)

    # Combine all input kinds
    return entity_inputs + state_inputs + event_inputs


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Return all outcomes produced by the process in the given scope.
    """
    # Outcomes from events
    _, event_outcomes = _parse_events_list(doc, scope)

    # Outcomes from motion log rows
    motion_outcomes = _parse_motion_log_outcomes(doc, scope)

    # Combine
    return event_outcomes + motion_outcomes


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """
    Constants stated explicitly in the scope.
    This document contains none, so return an empty mapping.
    """
    return {}


# ---- step 2: forward model ----
def simulate(doc: Dict[str, Any], scope: str, inputs, params, start=None, horizon=None):
    """
    Returns the recorded outcomes that belong to *scope*, but only those that
    occur between ``start`` (inclusive) and ``horizon`` (inclusive), and only if
    the entities involved have an input in the ``inputs`` list and have already
    arrived.

    The function simply reproduces the ground‑truth outcomes appearing in the
    Events list and in the Motion log of the scope; it does not perform any
    dynamic simulation.  The helper functions defined earlier are used to
    locate the relevant nodes and to extract rows.
    """
    # ------------------------------------------------------------------
    # 1.  Locate the scope node
    # ------------------------------------------------------------------
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # ------------------------------------------------------------------
    # 2.  Determine which entities appear in the caller‑supplied inputs
    # ------------------------------------------------------------------
    entities_involved = set()
    arrival_time: dict[str, float] = {}
    for inp in inputs:
        kind = inp.get("kind")
        if kind in {"entity_definition", "entity_arrival", "initial_state"}:
            ent_ids = inp.get("entities", [])
            if isinstance(ent_ids, list):
                entities_involved.update(ent_ids)
            else:
                entities_involved.add(ent_ids)
            if kind == "entity_arrival":
                arrival_time[inp["entities"][0]] = float(inp.get("time", 0.0))

    # ------------------------------------------------------------------
    # 3.  Gather all outcomes that belong to the scope
    # ------------------------------------------------------------------
    outcomes: list[dict] = []

    # 3.1  Outcomes from the Events list
    evt_node = None
    for c in children(doc, scope_node):
        if c["title"].endswith(": Events"):
            evt_node = c
            break
    if evt_node:
        for idx, line in enumerate(evt_node.get("lines", [])):
            m = re.match(r"Frame\s+(\d+)\s*:\s*Object\s+(\d+)(?:\s*\(([^)]*)\))?\s*(.*)", line)
            if not m:
                continue
            t = float(m.group(1))
            obj_id = m.group(2)
            rest = m.group(4).strip()
            if "collides with Object" in rest:
                other_id = re.search(r"collides with Object\s+(\d+)", rest)
                other_id = other_id.group(1) if other_id else None
                outcomes.append({
                    "time": t,
                    "kind": "collision",
                    "entities": [obj_id, other_id] if other_id else [obj_id],
                    "value": None,
                    "src": [[evt_node["node_id"], idx]]
                })
            elif "exits the scene" in rest:
                outcomes.append({
                    "time": t,
                    "kind": "entity_exit",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[evt_node["node_id"], idx]]
                })
            else:
                outcomes.append({
                    "time": t,
                    "kind": "event",
                    "entities": [obj_id],
                    "value": None,
                    "src": [[evt_node["node_id"], idx]]
                })

    # 3.2  Outcomes from the Motion log
    mov_node = None
    for c in children(doc, scope_node):
        if c["title"].endswith(": Motion log"):
            mov_node = c
            break
    if mov_node:
        for idx, row in table_rows(mov_node):
            try:
                t = float(row["frame"])
            except Exception:
                continue
            obj_field = row["object"]
            m_obj = re.match(r"(\d+)\s+", obj_field)
            if not m_obj:
                continue
            obj_id = m_obj.group(1)
            outcomes.append({
                "time": t,
                "kind": "state_record",
                "entities": [obj_id],
                "value": None,
                "src": [[mov_node["node_id"], idx]]
            })

    # ------------------------------------------------------------------
    # 4.  Determine the time window to keep
    # ------------------------------------------------------------------
    if start is None:
        start = float("-inf")
    if horizon is None:
        horizon = float("inf")

    # ------------------------------------------------------------------
    # 5.  Filter outcomes by time window and entity arrival
    # ------------------------------------------------------------------
    def allowed(o: dict) -> bool:
        t = o["time"]
        if t < start or t > horizon:
            return False
        for e in o["entities"]:
            if e not in entities_involved:
                return False
            if t < arrival_time.get(e, 0.0):
                return False
        return True

    final_out = [o for o in outcomes if allowed(o)]
    # Keep deterministic order
    final_out.sort(key=lambda r: r["time"])
    return final_out
